  "feat.title": "ফিচার",
  "feat.subtitle": "আপনার PDF দিয়ে যা যা করতে পারেন, আর তা কীভাবে কাজ করে।",
  "feat.f1t": "আপনার ফাইল আপনার ডিভাইসেই থাকে",
  "feat.f1b": "মার্জ, স্প্লিট, কম্প্রেস, সাইন, রিড্যাক্ট, OCR এবং বেশিরভাগ কনভার্শন আপনার ব্রাউজারের ভেতরেই চলে। কিছুই আপলোড হয় না।",
  "feat.f2t": "আসল রিড্যাকশন",
